def _fix_customers_name(customers):
    return [valid_customer for customer in customers for valid_customer in VALID_CUSTOMERS if
            customer.strip().lower() == valid_customer.lower()]


def validate_customers_list(customers):
    if not customers:
        raise ValueError("Validation failed. Please define variable 'customers_list' correctly.")

    customers = [customer.lstrip() for customer in customers.split(",")] if isinstance(customers, str) else customers
    valid_customers = _fix_customers_name(customers)

    assert len(customers) == len(valid_customers) and ('Generic' not in valid_customers or len(customers) == 1), \
        f"Validation failed. Please define variable 'customers_list' correctly.\nYour customers list: {customers}"
    return valid_customers


class CSV4AllTestReporter(reporting_portal):
    scout = scout()

    def __init__(self, test_name, qc_domain, qc_id, qc_project, customers_list,
                 report_comment, topology, sw_build=None, uuf_case_type=None, tool="WebEM", notifications=None):
        self.cm_execution = os.environ.get("CM_EXECUTION_ID")
        self.uuf_case_type = uuf_case_type
        self.report_dict = defaultdict(dict)
        self.test_id = None
        self.scout_tl_name = None
        self.location = self.get_location()
        self.organization = self.get_organization(self.location)
        self.ca = self.get_competence_area()
        self.current_iteration_end_time = None
        self.current_iteration_start_time = None
        self.build = sw_build
        self.test_name = test_name
        self.qc_project = qc_project
        self.qc_id = qc_id
        self.qc_domain = qc_domain
        self.report_comment = f"CSV4ALL{'_' + str(report_comment) if report_comment is not None else ''}"
        self.customers_list = validate_customers_list(customers_list)
        self.testline_type = topology
        self.tool = tool
        self.notifications = notifications
        self.tester_name = get_builtin_value("TESTER_NAME")

    @classmethod
    def create_reporter(cls, qc_domain, qc_id, qc_project, customers_list,
                        report_comment, sw_build=None, topology=None, notifications=None):
        customers_list = validate_customers_list(customers_list)
        test_name = BuiltIn().get_variable_value("${TEST_NAME}")
        if not cls.validate_organization_report_data():
            return
        if cls.validate_qc_report_data(qc_domain, qc_id, qc_project):
            return cls(test_name=test_name, qc_domain=qc_domain, qc_id=qc_id, qc_project=qc_project,
                       customers_list=customers_list, report_comment=report_comment, sw_build=sw_build,
                       topology=topology, notifications=notifications)
        return cls(test_name=test_name, qc_domain="", qc_id="", qc_project="",
                   customers_list=customers_list, report_comment=report_comment, sw_build=sw_build,
                   topology=topology, notifications=notifications)

    @staticmethod
    def validate_qc_report_data(qc_domain, qc_id, qc_project):
        if not all([qc_domain, qc_id, qc_project]):
            return False
        return True

    @classmethod
    def validate_organization_report_data(cls):
        location = cls.get_location()
        if not all([cls.get_competence_area(), location, cls.get_organization(location)]):
            test_logger("Valid variables: ${RP_CA}, ${RP_ORGANIZATION}, ${RP_LOCATION} in Test Suite "
                        "are mandatory to perform reporting to RP!", "WARN")
            return False
        return True

    def set_variables_from_node(self, node):
        node.product = self._get_list_of_modules(node.radioModules)
        module_lists = [
            self._get_list_of_modules(node.systemModules),
            self._get_list_of_modules(node.basebandModules),
            self._get_list_of_modules(node.radioModules)
        ]
        node.hw_id = "+".join([module for module in module_lists if module])
        test_logger(node.hw_id)
        node.sa_nsa_variant = node.btsverify.cells_verifier.gnb_cu_type
        node.duplex_variant = node.btsverify.cells_verifier.duplex_variant
        if not self.build:
            if self.uuf_case_type in ["upgrade", "activation_reset"]:
                self.build = node.target_sw
            else:
                self.build = node.get_active_sw()
        node.build = self.build
        node.scout_tl_name = node.testline_scout_name
        self.scout_tl_name = node.scout_tl_name

    @staticmethod
    def _get_list_of_modules(modules):
        modules_type = [module.get("Module Type") for module in modules.values()]
        return "+".join(sorted([f"{modules_type.count(module)}{module}" for module in set(modules_type)]))

    @method_decorator()
    def fetch_scout_and_set_test_id(self, node):
        node.test_id = self.fetch_scout_id(node)
        self.add_bts_to_report(mrbts_id=node.mrbts_id, build=node.build,
                               role=None, scout_scf_id=node.test_id)

    @method_decorator()
    def fetch_scout_id(self, node):
        def get_tl_scout_status():
            try:
                scout_tl_status = self.scout.get_scout_testline_status()
                test_logger(f"Scout TL status: {scout_tl_status}", "DEBUG")
                scout_tl_monitor_status = self.scout.get_testline_monitor_status()
                test_logger(f"Scout TL Monitor status: {scout_tl_monitor_status}", "DEBUG")
            except Exception:
                pass

        try:
            wait_until_success(300, 5, self.scout.setup_scout, scout_testline_name=node.scout_tl_name)
            get_tl_scout_status()
            scout_id_internal = wait_until_success(300, 20, self.scout.request_scf, use_scout_internal_id=True)
            if not self.test_id:
                use_internal = not self.cm_execution
                self.test_id = wait_until_success(300, 20, self.scout.request_scf, use_scout_internal_id=use_internal)
            test_logger(f"Scout fetch successful for TL {node.scout_tl_name}, "
                        f"scout_id_internal: {scout_id_internal}, "
                        f"scout_id_cloud: {self.test_id}")
            return scout_id_internal
        except FunctionTimeoutException as fetch_err:
            test_logger("Config Id not added to test data. Scout fetch failed", "warn")
            test_logger(f"Scout fetch failed: {fetch_err.exception}")
            if self.notifications:
                self.notifications.send_email(body=f"{str(fetch_err)}\nException: {str(fetch_err.exception)}",
                                              subject=f"SCOUT FETCH FAILED FOR {node.scout_tl_name}", text_type="plain")
            return ""
        finally:
            self.scout.teardown_scout_api()

    @method_decorator()
    def report_result_to_uuf_dashboard(self, node, result, kpi, iteration_no, kpi_results=''):
        uuf_downtime = {f"{self.uuf_case_type}_downtime": str(kpi)}

        def parse_uuf_report_args(**kwargs):
            self.log_report_args(**kwargs)
            parsed_report_args = {key: value for key, value in kwargs.items()}
            parsed_report_args["sa/nsa_variant"] = parsed_report_args["sa_nsa_variant"]
            parsed_report_args["tdd/fdd_variant"] = parsed_report_args["tdd_fdd_variant"]
            parsed_report_args.__delitem__("sa_nsa_variant")
            parsed_report_args.__delitem__("tdd_fdd_variant")
            return parsed_report_args

        report_args = parse_uuf_report_args(name=f"UUF4ALL_{self.uuf_case_type.upper()}_TEST",
                                            ca=self.ca,
                                            location=self.location,
                                            organization=self.organization,
                                            result=result,
                                            uuf_test=True,
                                            comment=self.report_comment,
                                            testline=node.scout_tl_name,
                                            build=node.build,
                                            parameter_1=node.build if "reset" in self.uuf_case_type else node.source_sw,
                                            qc_id=self.qc_id,
                                            qc_domain=self.qc_domain,
                                            qc_project=self.qc_project,
                                            username=self.tester_name,
                                            starttime=self.current_iteration_start_time,
                                            endtime=self.current_iteration_end_time,
                                            customers=self.customers_list,
                                            tool=self.tool,
                                            case_type=self.get_case_type(),
                                            links={},
                                            label=self.testline_type,
                                            product=node.product,
                                            sa_nsa_variant=node.sa_nsa_variant,
                                            tdd_fdd_variant=node.duplex_variant,
                                            hw_id=node.hw_id,
                                            tc_execution_id=node.test_id,
                                            rfrl_versions=self._get_rfrl_version(),
                                            kpi_results=kpi_results,
                                            **uuf_downtime)
        report_link = self.report_to_rp(**report_args)
        test_logger(f"Link to report : {report_link}", "INFO", hyperlink=True)
        result_dict = {"Result": result, "Link to report": report_link}
        self.report_dict[node.node_alias][iteration_no] = result_dict

    @staticmethod
    def _get_time_now():
        return datetime.now().strftime('%Y%m%d %H:%M:%S.000')

    def get_start_time(self):
        self.current_iteration_start_time = self._get_time_now()

    def get_end_time(self):
        self.current_iteration_end_time = self._get_time_now()

    @method_decorator()
    def report_summary_to_reporting_portal(self, kpi_results, result, test_results: dict, test_iterations: int) -> None:
        executed_iterations = sum(1 for nodes_results in test_results.values() if nodes_results)
        if self.cm_execution and test_iterations > 1:
            self.add_to_test_data(str({"test_loops": executed_iterations}))
        if not self.cm_execution:
            self.log_report_args(name=self.test_name,
                                 result=result,
                                 ca=self.ca,
                                 location=self.location,
                                 organization=self.organization,
                                 testline=self.scout_tl_name,
                                 build=self.build,
                                 qc_domain=self.qc_domain,
                                 qc_project=self.qc_project,
                                 qc_id=self.qc_id,
                                 label=self.testline_type,
                                 tool=self.tool,
                                 kpi_results=kpi_results,
                                 links={},
                                 tc_execution_id=self.test_id,
                                 executed_test_loops=executed_iterations
                                 )
            link_to_rp = self.report_to_rp(
                name=self.test_name,
                result=result,
                ca=self.ca,
                location=self.location,
                organization=self.organization,
                testline=self.scout_tl_name,
                build=self.build,
                qc_domain=self.qc_domain,
                qc_project=self.qc_project,
                qc_id=self.qc_id,
                label=self.testline_type,
                username=self.tester_name,
                tool=self.tool,
                kpi_results=kpi_results,
                links={},
                tc_execution_id=self.test_id,
                executed_test_loops=executed_iterations
            )
            result_dict = {"Result": result, "Link to report": link_to_rp}
            self.report_dict["Summary Result"] = result_dict
            test_logger(f"Results:\n{json.dumps(self.report_dict, indent=4)}", "info", console=False)

    @staticmethod
    def get_competence_area():
        ca = get_variable("RP_CA")
        if ca:
            if re.match("|".join(RP_CA_LIST), ca):
                return ca
            test_logger(f"You have provided not valid value under ${{RP_CA}}: {ca}", "WARN")
        else:
            test_logger(f"Variable ${{RP_CA}} in Test Suite is required otherwise report to RP will be disabled!",
                        "WARN")
        test_logger(f"Valid values for Competence Area: {RP_CA_LIST}", "WARN")
        force_tags = get_variable("TEST_TAGS")
        if [tag for tag in force_tags if "CA_" in tag]:
            test_logger("Force Tag setting of CA is depreciated and will be removed. Please declare test variable: "
                        "${RP_CA}", "WARN")
            return [tag[3::] for tag in force_tags if "CA_" in tag][0]
        return ""

    def set_tags(self):
        if None not in [self.qc_id, self.qc_domain, self.qc_project]:
            BuiltIn().set_tags(f"QCD_{self.qc_domain}", f"QCP_{self.qc_project}", f"QC_{self.qc_id}")

    @staticmethod
    def log_report_args(**kwargs):
        test_logger(f"Report Arguments: {kwargs}", "debug", console=False)

    @staticmethod
    def get_location():
        location = get_variable("RP_LOCATION")

        if location:
            if re.match("|".join(RP_LOCATION_LIST), location):
                return location
            test_logger(f"You have provided not valid value under ${{RP_LOCATION}}: {location}", "WARN")
        else:
            test_logger(f"Variable ${{RP_LOCATION}} in Test Suite is required otherwise "
                        f"report to RP will be disabled!", "WARN")
        test_logger(f"Valid values for ${{RP_LOCATION}}: {RP_LOCATION_LIST}", "WARN")
        return ""

    @staticmethod
    def get_organization(location: str) -> str:
        organization = get_variable("RP_ORGANIZATION")
        if organization:
            organization_split = organization.rsplit("_T", 1)
            if len(organization_split) == 2:
                location_part = organization_split[0]
                trailing_part = f'T{organization_split[-1]}'
                location_part_valid = re.match("|".join(RP_LOCATION_LIST), location_part)
                if location in location_part:
                    if location_part_valid and "CIS" in organization \
                            or bool(re.search(r'T\d{2}(?:_\d{1,2})?$', trailing_part)):
                        return organization
                    test_logger(f"You have provided not valid value under ${{RP_ORGANIZATION}}: {organization}. "
                                f"Example correct value: VRF_WRO3_T03", "WARN")
                else:
                    test_logger(f"You have provided not valid value under ${{RP_ORGANIZATION}}: {organization}. "
                                f"It has to match with location: {location}", "WARN")
        else:
            test_logger(f"Variable ${{RP_ORGANIZATION}} in Test Suite is required otherwise report to RP will be "
                        f"disabled! Example correct value: VRF_WRO3_T03", "WARN")
        return ""

    def _check_if_sut_id_already_reported(self, sut_id: str) -> None:
        try:
            logging.getLogger("taf.sw.reporting_portal").disabled = True
            super()._check_if_sut_id_already_reported(sut_id)
        finally:
            logging.getLogger("taf.sw.reporting_portal").disabled = False

    @staticmethod
    def _get_rfrl_version() -> dict:
        package = str(pkg_resources.get_distribution('taf-rfrl-csv4all')).replace("-", ".")
        return {package.split(" ")[0]: package.split(" ")[1]}

    def get_case_type(self):
        if "reset" in self.uuf_case_type:
            return "Reset"
        return self.uuf_case_type.title()

    @method_decorator()
    def add_to_test_data(self, data: str):
        super().add_to_test_data(data=data)
